const r = await tools.exec_command({"cmd":"/opt/homebrew/bin/node --input-type=module <<'NODE'
import { execFileSync } from 'node:child_process';
const ref = 'sf-next/next';
const show = (path) => execFileSync('git', ['show', `${ref}:${path}`], {encoding:'utf8'});
const list = JSON.parse(show('release-packages.json'));
const seenSlugs = new Set();
const seenNames = new Set();
const errors = [];
const rows = [];
for (const entry of list) {
  if (seenSlugs.has(entry.slug)) errors.push(`duplicate slug ${entry.slug}`);
  if (seenNames.has(entry.name)) errors.push(`duplicate name ${entry.name}`);
  seenSlugs.add(entry.slug); seenNames.add(entry.name);
  try {
    const pkg = JSON.parse(show(`${entry.path}/package.json`));
    if (pkg.name !== entry.name) errors.push(`${entry.slug}: allowlist=${entry.name}, manifest=${pkg.name}`);
    rows.push({ ...entry, version: pkg.version, private: pkg.private === true, hasBuild: Boolean(pkg.scripts?.build), hasTest: Boolean(pkg.scripts?.test), access: pkg.publishConfig?.access ?? null });
  } catch (error) {
    errors.push(`${entry.slug}: ${String(error.message).split('\n')[0]}`);
  }
}
const summary = {
  count: list.length,
  errors,
  private: rows.filter(r => r.private).map(r => r.name),
  missingBuild: rows.filter(r => !r.hasBuild).map(r => r.name),
  missingTest: rows.filter(r => !r.hasTest).map(r => r.name),
  scopedWithoutPublicAccess: rows.filter(r => r.name.startsWith('@') && r.access !== 'public').map(r => r.name),
};
console.log(JSON.stringify(summary, null, 2));
