const r = await tools.exec_command({"cmd":"/opt/homebrew/bin/node --input-type=module <<'NODE'
import { execFileSync } from 'node:child_process';
const show=(ref,p)=>execFileSync('git',['show',`${ref}:${p}`],{encoding:'utf8',stdio:['ignore','pipe','ignore']});
const files=(ref)=>execFileSync('git',['ls-tree','-r','--name-only',ref],{encoding:'utf8'}).trim().split('\n').filter(p=>p.endsWith('/package.json')||p==='package.json');
const devNames=new Map();
for(const path of files('origin/dev')){
  try{const pkg=JSON.parse(show('origin/dev',path)); if(pkg.name) {if(!devNames.has(pkg.name))devNames.set(pkg.name,[]);devNames.get(pkg.name).push(path);}}catch{}
}
const release=JSON.parse(show('sf-next/next','release-packages.json'));
const rows=release.map(e=>{
 const pkg=JSON.parse(show('sf-next/next',`${e.path}/package.json`));
 const devPaths=devNames.get(pkg.name)??[];
 return {...e,version:pkg.version,excludedShared:e.path.startsWith('packages/'),excludedDev:devPaths.length>0,devPaths};
});
const candidates=rows.filter(r=>!r.excludedShared&&!r.excludedDev);
console.log(JSON.stringify({
 total:rows.length,
 excludedShared:rows.filter(r=>r.excludedShared).length,
 excludedDevOnly:rows.filter(r=>!r.excludedShared&&r.excludedDev).length,
 candidates:candidates.length,
